// mulligan: a do-over for shell commands. Before Claude runs a Bash command
// that destroys files (the same classifier last-look uses: rm -r, find
// -delete, xargs rm, git clean, git reset --hard, git checkout or restore over
// changes, git worktree remove, a redirect over a file), it saves what that
// command can destroy: the paths it names, or git's tracked changes as a
// commit object (`git stash create`, which moves no ref), or the untracked
// files, or the whole project when the targets are only known as it runs.
// /mulligan lists them and puts one back after a confirm press.
//
// Saved before the tool runs, into a pending archive; kept only once the
// command really ran (a hold beneath that refuses it leaves no snapshot). Ten
// per project, in slots under ~/.claude/mulligan/<project key>/, reused in
// turn: nothing is ever deleted with rm. A restore writes files back over what
// is there and deletes nothing newer, then tells Claude to re-read.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { MulliganSnapshot } from '../types'
import { classify } from './classify'
import { agoWords, clean, isEmpty, oneLine, planFor, projectKey, restoreNote, scopeWords, shown, sizeWords, treePlan } from './plan'
import type { Plan } from './plan'

const SNAPSHOTS = { plugin: 'mulligan', key: 'snapshots' } as const
const BAND = { plugin: 'mulligan', key: 'band' } as const
const VIEW = { plugin: 'mulligan', key: 'view' } as const
const snapshots = atom(SNAPSHOTS, [])
const band = atom(BAND, null)
const view = atom(VIEW, { kind: 'list', confirm: 0 })

/** Snapshots kept per project, and so the archive slots. */
export const KEEP = 10
const BAND_MS = 8_000
const PANE = 'mulligan'
const TAR_MS = 20_000
const DIFF_FILES = 50
/** Origins that are the person: typed, the phone bridge, the desktop app's box. */
const PERSON = new Set(['composer', 'bridge', 'sdk'])
/** git never takes the index lock for us, never prompts, and speaks C. */
const ENV = { LC_ALL: 'C', GIT_OPTIONAL_LOCKS: '0', GIT_TERMINAL_PROMPT: '0' }
const SHA = /^[0-9a-f]{40,64}$/

export type Settings = { always: RegExp | undefined; ignore: RegExp | undefined; capBytes: number }

/** The person's settings: patterns that do not compile are left out, the cap clamped. */
export function readSettings(options: Record<string, unknown>): Settings {
  const pattern = (v: unknown) => {
    if (typeof v !== 'string' || v.trim() === '' || v.length > 500) return undefined
    try {
      return new RegExp(v, 'i')
    } catch {
      return undefined
    }
  }
  const mb = typeof options.capMB === 'number' && Number.isFinite(options.capMB) ? Math.min(5_000, Math.max(1, options.capMB)) : 200
  return { always: pattern(options.always), ignore: pattern(options.ignore), capBytes: Math.round(mb * 1_000_000) }
}

type Index = { v: 1; next: number; snapshots: MulliganSnapshot[] }
type Where = { root: string; cwd: string; home: string | undefined; base: string }
type Pending = { command: string; plan: Plan; sha?: string; archive?: string; bytes: number; where: Where }
type Prepared = { pending?: Pending; skip?: { text: string; tone: 'subtle' | 'warning' } }

let settings: Settings = readSettings({})

// The switch (`enabled`, which /config and the modmyclaude hub flip): off, Mulligan saves
// nothing before any command and draws no band. The do-overs it already saved stay, and
// /mulligan restore still puts one back: they are the person's files, and turning the
// switch on just to reach them would start saving again, which can reuse the oldest slot.
// The engine reloads the mod with the new value; the config.set hook below is the same
// switch at once.
let isOn = true
const OFF_TEXT = 'Mulligan is off. /mods or /config turns it on.'

/** Index writes one at a time: Claude can run two commands at once. */
let chain: Promise<unknown> = Promise.resolve()

/** Runs `work` after every index write before it; a failure never blocks the next one. */
function queued<T>(work: () => Promise<T>): Promise<T> {
  const done = chain.then(work)
  chain = done.catch(() => undefined)
  return done
}
let pendingCount = 0

function debug($: EngineInterface, error: unknown): void {
  $.ui.log(`mulligan: ${error instanceof Error ? error.message : String(error)}`, { to: 'debug' })
}

function run($: EngineInterface, argv: string[], cwd: string, stdin?: string, timeoutMs = 15_000) {
  return $.process.run(argv, { cwd, env: ENV, timeoutMs, ...(stdin === undefined ? {} : { stdin }) })
}

async function whereNow($: EngineInterface): Promise<Where | null> {
  const [root, cwd, config, home] = await Promise.all([$.session.root(), $.session.cwd(), $.env.get('CLAUDE_CONFIG_DIR'), $.env.get('HOME')])
  const dir = config ? config.replace(/\/+$/, '') : home ? `${home.replace(/\/+$/, '')}/.claude` : undefined
  if (dir === undefined) return null
  return { root, cwd, home: home || undefined, base: `${dir}/mulligan/${projectKey(root)}` }
}

async function isGitAt($: EngineInterface, root: string): Promise<boolean> {
  try {
    const r = await run($, ['git', 'rev-parse', '--is-inside-work-tree'], root)
    return r.exitCode === 0 && r.stdout.trim() === 'true'
  } catch {
    return false
  }
}

/** The project's snapshot list, from its folder; empty when there is none or it does not read. */
async function readIndex($: EngineInterface, base: string): Promise<Index> {
  try {
    const parsed = JSON.parse(await $.fs.read(`${base}/index.json`)) as Partial<Index>
    if (parsed.v !== 1 || typeof parsed.next !== 'number' || !Array.isArray(parsed.snapshots)) throw new Error('not an index')
    return { v: 1, next: parsed.next, snapshots: parsed.snapshots.filter(s => typeof s?.n === 'number').slice(-KEEP) }
  } catch {
    return { v: 1, next: 1, snapshots: [] }
  }
}

async function sizeOf($: EngineInterface, base: string, name: string): Promise<number> {
  try {
    return (await $.fs.list(base)).find(entry => entry.name === name)?.size ?? 0
  } catch {
    return 0
  }
}

/** Empties one of our own archives: the API has no delete, and an empty file costs nothing. */
async function emptyArchive($: EngineInterface, base: string, name: string): Promise<void> {
  if (!/^(?:slot-\d|pending-\d+)\.tar$/.test(name)) return
  await $.fs.write(`${base}/${name}`, '').catch(() => undefined)
}

/**
 * Before the command runs: what it can destroy, saved into a pending archive
 * (and a git object). A skip says why nothing was saved, when that is news.
 */
async function prepare($: EngineInterface, shellCommand: string): Promise<Prepared> {
  if (settings.ignore?.test(shellCommand)) return {}
  const where = await whereNow($)
  if (where === null) return {}
  const isGit = await isGitAt($, where.root)
  let plan = planFor(classify(shellCommand, where.home === undefined ? {} : { home: where.home }), where.cwd, where.root, isGit)
  if (settings.always?.test(shellCommand)) plan = { ...treePlan(isGit), outside: plan?.outside ?? [], notes: plan?.notes ?? [] }
  if (plan === null) return {}
  const cmd = oneLine(clean(shellCommand), 48)
  if (isEmpty(plan.scope)) {
    return plan.outside.length > 0 ? { skip: { text: `mulligan: no do-over for "${cmd}": ${clean(plan.outside[0]!)} is outside the project.`, tone: 'subtle' } } : {}
  }
  const { root, base } = where
  let sha: string | undefined
  if (plan.scope.isTracked) {
    const made = await run($, ['git', 'stash', 'create'], root).catch(() => undefined)
    sha = made?.exitCode === 0 ? made.stdout.trim() : undefined
    if (!sha) {
      // Nothing changed since the last commit: HEAD is the tracked files' state.
      const head = await run($, ['git', 'rev-parse', '--verify', 'HEAD'], root).catch(() => undefined)
      sha = head?.exitCode === 0 ? head.stdout.trim() : undefined
    }
    if (sha !== undefined && !SHA.test(sha)) sha = undefined
  }

  // The files to copy: the whole tree without git; else the untracked ones and the named paths that exist.
  const isWholeTree = plan.scope.isTree && !plan.scope.isTracked
  const files: string[] = []
  if (!isWholeTree) {
    if (plan.scope.isUntracked) {
      const listed = await run($, ['git', 'ls-files', '--others', '--exclude-standard', '-z', '--', '.'], root).catch(() => undefined)
      if (listed?.exitCode === 0) files.push(...listed.stdout.split('\0').filter(name => name !== ''))
    }
    for (const path of plan.scope.paths) {
      if (await $.fs.exists(path).catch(() => false)) files.push(shown(path, root))
    }
  }
  let archive: string | undefined
  let bytes = 0
  if (isWholeTree || files.length > 0) {
    const name = `pending-${++pendingCount}.tar`
    await run($, ['mkdir', '-p', base], root)
    const argv = isWholeTree
      ? ['tar', '-cf', `${base}/${name}`, '--exclude=.git', '--exclude=node_modules', '.']
      : ['tar', '-cf', `${base}/${name}`, '--exclude=.git', '--null', '-T', '-']
    let ok = false
    try {
      const made = await run($, argv, root, isWholeTree ? undefined : `${files.join('\0')}\0`, TAR_MS)
      ok = made.exitCode === 0
    } catch {
      ok = false // too slow: too big
    }
    bytes = ok ? await sizeOf($, base, name) : 0
    if (!ok || bytes > settings.capBytes) {
      await emptyArchive($, base, name)
      const why = ok ? `too big to save (${sizeWords(bytes)})` : 'could not be saved'
      if (sha === undefined) return { skip: { text: `mulligan: ${why}; "${cmd}" runs without a do-over.`, tone: 'warning' } }
      plan = { ...plan, notes: [...plan.notes, `the files it names were ${why}`] }
      bytes = 0
    } else {
      archive = name
    }
  }
  if (sha === undefined && archive === undefined) return {} // nothing there to lose (a redirect to a new file)
  return { pending: { command: shellCommand, plan, ...(sha === undefined ? {} : { sha }), ...(archive === undefined ? {} : { archive }), bytes, where } }
}

/** After the command ran: the pending snapshot takes its slot, the oldest gives way. */
async function commit($: EngineInterface, p: Pending): Promise<MulliganSnapshot> {
  const { base, root } = p.where
  const index = await readIndex($, base)
  const n = index.next
  const slot = `slot-${(n - 1) % KEEP}.tar`
  if (p.archive !== undefined) {
    const moved = await run($, ['mv', '-f', `${base}/${p.archive}`, `${base}/${slot}`], root)
    if (moved.exitCode !== 0) throw new Error(`could not keep the snapshot: ${moved.stderr.trim()}`)
  }
  const snap: MulliganSnapshot = {
    n,
    at: await $.clock.now(),
    command: oneLine(clean(p.command), 160),
    scope: scopeWords(p.plan.scope, root),
    ...(p.sha === undefined ? {} : { sha: p.sha }),
    ...(p.archive === undefined ? {} : { archive: slot }),
    bytes: p.bytes,
  }
  const kept = [...index.snapshots, snap].slice(-KEEP)
  for (const old of index.snapshots) {
    if (!kept.includes(old) && old.archive !== undefined && old.archive !== snap.archive) await emptyArchive($, base, old.archive)
  }
  await $.fs.write(`${base}/index.json`, JSON.stringify({ v: 1, next: n + 1, snapshots: kept } satisfies Index))
  await update($, snapshots, () => kept)
  return snap
}

async function showBand($: EngineInterface, text: string, tone: 'subtle' | 'warning'): Promise<void> {
  const until = (await $.clock.now()) + BAND_MS
  await update($, band, () => ({ text, tone, until }))
  $.clock.after(BAND_MS, () => {
    void update($, band, b => (b !== null && b.until <= until ? null : b)).catch(() => undefined)
  })
}

async function findSnapshot($: EngineInterface, n: number): Promise<{ where: Where; snap: MulliganSnapshot } | null> {
  const where = await whereNow($)
  if (where === null) return null
  const snap = (await readIndex($, where.base)).snapshots.find(s => s.n === n)
  return snap === undefined ? null : { where, snap }
}

/** Puts snapshot n back: files written over what is there, nothing newer deleted; Claude is told. */
async function restore($: EngineInterface, n: number): Promise<string> {
  const found = await findSnapshot($, n)
  if (found === null) return `mulligan: there is no snapshot ${n} for this project.`
  const { where, snap } = found
  const problems: string[] = []
  if (snap.sha !== undefined && SHA.test(snap.sha)) {
    const r = await run($, ['git', 'restore', '--overlay', `--source=${snap.sha}`, '--worktree', '--', '.'], where.root).catch(() => undefined)
    if (r?.exitCode !== 0) problems.push(`tracked files (${oneLine(r?.stderr ?? 'git did not answer', 80)})`)
  }
  if (snap.archive !== undefined) {
    if ((await sizeOf($, where.base, snap.archive)) === 0) problems.push('its files (the archive is gone)')
    else {
      const r = await run($, ['tar', '-xf', `${where.base}/${snap.archive}`], where.root, undefined, 60_000).catch(() => undefined)
      if (r?.exitCode !== 0) problems.push(`files (${oneLine(r?.stderr ?? 'tar did not finish', 80)})`)
    }
  }
  try {
    await $.session.append({ message: { type: 'user', content: [{ type: 'text', text: restoreNote(snap.command, n) }] } })
  } catch (error) {
    debug($, error)
  }
  return problems.length === 0 ? `mulligan: restored #${n} (${snap.scope}). Claude was told to re-read files.` : `mulligan: #${n} restored in part; not put back: ${problems.join('; ')}.`
}

/** What differs now from snapshot n: tracked files through git, copied files one by one. */
async function diffLines($: EngineInterface, n: number): Promise<string[]> {
  const found = await findSnapshot($, n)
  if (found === null) return [`There is no snapshot ${n} for this project.`]
  const { where, snap } = found
  const lines: string[] = []
  if (snap.sha !== undefined && SHA.test(snap.sha)) {
    const r = await run($, ['git', 'diff', '--name-status', snap.sha, '--', '.'], where.root).catch(() => undefined)
    const words: Record<string, string> = { M: 'changed', D: 'deleted', A: 'new since', T: 'changed' }
    for (const line of (r?.exitCode === 0 ? r.stdout : '').split('\n').filter(Boolean).slice(0, 100)) {
      const [status = '', path = ''] = line.split('\t')
      lines.push(`${words[status[0] ?? ''] ?? 'differs'}: ${path}`)
    }
  }
  if (snap.archive !== undefined && (await sizeOf($, where.base, snap.archive)) > 0) {
    const file = `${where.base}/${snap.archive}`
    const listed = await run($, ['tar', '-tf', file], where.root).catch(() => undefined)
    const entries = (listed?.exitCode === 0 ? listed.stdout : '').split('\n').filter(name => name !== '' && !name.endsWith('/'))
    for (const entry of entries.slice(0, DIFF_FILES)) {
      const path = `${where.root}/${entry.replace(/^\.\//, '')}`
      if (!(await $.fs.exists(path).catch(() => false))) {
        lines.push(`deleted: ${entry.replace(/^\.\//, '')}`)
        continue
      }
      const then = await run($, ['tar', '-xOf', file, '--', entry], where.root).catch(() => undefined)
      const now = await $.fs.read(path).catch(() => undefined)
      if (then?.exitCode === 0 && now !== undefined && then.stdout !== now) lines.push(`changed: ${entry.replace(/^\.\//, '')}`)
    }
    if (entries.length > DIFF_FILES) lines.push(`and ${entries.length - DIFF_FILES} more files not compared`)
  }
  return lines.length > 0 ? lines : ['Nothing differs: the files it holds are as they were.']
}

async function openPane($: EngineInterface): Promise<boolean> {
  try {
    return (await $.ui.open({ id: PANE, title: 'mulligan', focus: true, closeOnEscape: true })).isPlaced
  } catch {
    return false
  }
}

/** The list as the project's folder has it (another session in this project may have added one). */
async function syncList($: EngineInterface): Promise<void> {
  const where = await whereNow($)
  if (where === null) return
  const list = (await readIndex($, where.base)).snapshots
  await update($, snapshots, () => list)
}

/** /mulligan: answers in the pane and toasts, never text Claude reads. */
async function command($: EngineInterface, args: string, origin: string): Promise<void> {
  const [verb = '', arg = ''] = args.trim().split(/\s+/)
  const action = verb.toLowerCase()
  const n = Number(arg)
  // Off, a restore is the one word that still runs.
  if (!isOn && action !== 'restore') return $.ui.toast(OFF_TEXT)
  await syncList($)
  if (action === '' || action === 'list') {
    await update($, view, () => ({ kind: 'list' as const, confirm: 0 }))
    if (!(await openPane($))) $.ui.toast(`mulligan: ${(await read($, snapshots)).length} do-overs for this project; the list draws in a pane, which only the terminal and the desktop app have.`)
    return
  }
  if (!Number.isInteger(n) || n < 1 || !(await read($, snapshots)).some(s => s.n === n)) {
    return $.ui.toast(`mulligan: there is no snapshot ${oneLine(clean(arg), 12) || '(none given)'} for this project.${isOn ? ' /mulligan lists them.' : ''}`)
  }
  if (action === 'restore') {
    await update($, view, () => ({ kind: 'list' as const, confirm: n }))
    if (!(await openPane($))) $.ui.toast('mulligan: a restore waits on a confirm in a pane, which only the terminal and the desktop app have.')
    return
  }
  if (action === 'diff') {
    const lines = await diffLines($, n)
    await update($, view, () => ({ kind: 'diff' as const, n, lines }))
    if (!(await openPane($))) $.ui.toast(`mulligan: #${n} differs in ${lines.length} place${lines.length === 1 ? '' : 's'}; the list draws in a pane.`)
    return
  }
  if (action === 'drop') {
    if (!PERSON.has(origin)) return $.ui.toast('mulligan: /mulligan drop runs only when you type it yourself.')
    const where = await whereNow($)
    if (where === null) return
    await queued(async () => {
      const index = await readIndex($, where.base)
      const gone = index.snapshots.find(s => s.n === n)
      if (gone?.archive !== undefined) await emptyArchive($, where.base, gone.archive)
      const kept = index.snapshots.filter(s => s.n !== n)
      await $.fs.write(`${where.base}/index.json`, JSON.stringify({ v: 1, next: index.next, snapshots: kept } satisfies Index))
      await update($, snapshots, () => kept)
    })
    return $.ui.toast(`mulligan: dropped #${n}.`)
  }
  $.ui.toast(`mulligan: unknown command "${oneLine(clean(verb), 24)}". /mulligan lists; restore <n>, diff <n>, drop <n>.`)
}

export const register: Register = (on, options) => {
  settings = readSettings(options)
  isOn = options.enabled !== false

  // Never touches a snapshot: the switch only stops new ones and the band.
  on('config.set', { key: 'mulligan.enabled' }, async ($, e, next) => {
    const set = await next(e)
    if (set.deny === undefined && typeof set.value === 'boolean') {
      isOn = set.value
      $.ui.invalidate('ui.render')
    }
    return set
  })

  on('session.start', async ($, e, next) => {
    try {
      await $.command.register({
        name: 'mulligan',
        description: 'List the do-overs saved before destructive commands, and put one back',
        argumentHint: '[restore <n> | diff <n> | drop <n>]',
        immediate: true,
      })
    } catch (error) {
      debug($, error)
    }
    return next(e)
  })

  // Saved before the tool runs; kept once it ran. The tool runs exactly once whatever happens here.
  // Off, no snapshot: the call passes as it came. One taken before a switch mid-command is still
  // kept (its files are already saved); its band is not drawn while off.
  on('tool.call', async ($, e, next) => {
    if (!isOn || e.tool !== 'Bash') return next(e)
    let prepared: Prepared = {}
    try {
      prepared = await prepare($, e.command)
    } catch (error) {
      debug($, error)
    }
    const ran = await next(e)
    try {
      const { pending, skip } = prepared
      if (ran.deny !== undefined) {
        // Held or refused beneath: the command never ran, so there is nothing to undo.
        if (pending?.archive !== undefined) await emptyArchive($, pending.where.base, pending.archive)
      } else if (pending !== undefined) {
        const snap = await queued(() => commit($, pending))
        const cmd = oneLine(clean(e.command), 40)
        const extra = [...pending.plan.notes, ...pending.plan.outside.map(path => `${clean(path)} is outside the project, not saved`)]
        await showBand($, `mulligan: saved a do-over before "${cmd}" (${snap.scope}) · /mulligan restore ${snap.n}${extra.length ? ` · ${extra.join('; ')}` : ''}`, extra.length ? 'warning' : 'subtle')
      } else if (skip !== undefined) {
        await showBand($, skip.text, skip.tone)
      }
    } catch (error) {
      debug($, error)
    }
    return ran
  })

  // One line under the other bands, for a few seconds after a snapshot or a skip.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!isOn) return next(e)
    const below = await next(e)
    const b = await read($, band)
    if (b === null || (await $.clock.now()) >= b.until || (e.surface !== 'terminal' && e.surface !== 'desktop')) return below
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        {below}
        <Text key="mulligan" dimColor={b.tone === 'subtle'} color={b.tone === 'warning' ? 'warning' : undefined}>
          {b.text}
        </Text>
      </Box>
    )
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const list = await read($, snapshots)
    const v = await read($, view)
    const now = await $.clock.now()
    // A restore waits on this press, on or off.
    const confirm = (s: MulliganSnapshot) => (
      <Box key="confirm" flexDirection="column" borderStyle="round" borderColor="warning" paddingX={1}>
        <Text key="ask">{`Put back ${clean(s.scope)} as it was before #${s.n}? Files it holds are written over what is there now; nothing newer is deleted.`}</Text>
        <Box key="choices" flexDirection="row" gap={2}>
          <Button
            key="yes"
            label="Yes, restore"
            onPress={async () => {
              const said = await restore($, s.n)
              await update($, view, () => ({ kind: 'list' as const, confirm: 0 }))
              $.ui.toast(said)
            }}
          />
          <Button key="cancel" label="Cancel" autoFocus onPress={() => void update($, view, () => ({ kind: 'list' as const, confirm: 0 }))} />
        </Box>
      </Box>
    )
    if (!isOn) {
      const asked = v.kind === 'list' ? list.find(s => s.n === v.confirm) : undefined
      return (
        <Box flexDirection="column" paddingX={1}>
          <Text key="off" dimColor>
            {OFF_TEXT}
          </Text>
          {asked === undefined ? null : confirm(asked)}
        </Box>
      )
    }
    if (v.kind === 'diff') {
      return (
        <Box flexDirection="column" paddingX={1}>
          <Text key="title" bold>{`#${v.n} against the files now`}</Text>
          {v.lines.map((line, i) => (
            <Text key={`diff-${i}`}>{clean(line)}</Text>
          ))}
          <Button key="back" label="Back to the list" onPress={() => void update($, view, () => ({ kind: 'list' as const, confirm: 0 }))} />
        </Box>
      )
    }
    return (
      <Box flexDirection="column" paddingX={1}>
        <Text key="title" bold>
          {list.length === 0 ? 'No do-overs yet for this project' : `${list.length} do-over${list.length === 1 ? '' : 's'} for this project`}
        </Text>
        {[...list].reverse().map(s => (
          <Box key={`snap-${s.n}`} flexDirection="column">
            <Box key="line" flexDirection="row" gap={1}>
              <Box key="n" width={4} flexShrink={0}>
                <Text dimColor>{`#${s.n}`}</Text>
              </Box>
              <Box key="command" flexGrow={1} flexShrink={1} minWidth={8}>
                <Text wrap="truncate-end">{clean(s.command)}</Text>
              </Box>
              <Box key="buttons" flexShrink={0} flexDirection="row" gap={1}>
                <Button key="restore" label="Restore" onPress={() => void update($, view, () => ({ kind: 'list' as const, confirm: s.n }))} />
                <Button
                  key="diff"
                  label="Diff"
                  onPress={async () => {
                    const lines = await diffLines($, s.n)
                    await update($, view, () => ({ kind: 'diff' as const, n: s.n, lines }))
                  }}
                />
              </Box>
            </Box>
            <Text key="about" dimColor>{`    ${clean(s.scope)}${s.bytes > 0 ? ` · ${sizeWords(s.bytes)}` : ''} · ${agoWords(now - s.at)}`}</Text>
            {v.confirm === s.n ? confirm(s) : null}
          </Box>
        ))}
        <Text key="note" dimColor>
          Files in this project only: a database, a remote or anything outside the folder is not covered.
        </Text>
      </Box>
    )
  })

  on('command.run', { command: 'mulligan' }, async ($, e) => {
    try {
      await command($, e.args, e.origin.kind)
    } catch (error) {
      debug($, error)
      $.ui.toast('mulligan: that command failed, and nothing changed.')
    }
    return {}
  })
}

files.hooks/classify.ts:
// The same file as last-look's hooks/classify.ts, copied so this mod installs on its own.
// Keep the two in step: a fix to one is a fix to both.

// Pure: given a Bash command string, which parts of it can destroy work?
//
// No `$`, no I/O: the hook measures what this finds. The rule of thumb is to
// catch what the spec names in every spelling a model actually writes (flag
// order, sudo and env prefixes, quoted paths, `cd x && ...`, subshells,
// `bash -c`, `$(...)`), and to leave look-alikes alone (`echo "rm -rf"`,
// `grep -r`, a single-file `rm`).

import { literal, parse } from './shell'
import type { Item, Part, RawWord, Redir, Seq } from './shell'

/** A word as the shell would hand it to the program, when that can be known. */
export type Word = {
  text: string
  /** False when it holds an expansion nobody can know ahead (`$X`, `$(...)`). */
  known: boolean
  /** True when unquoted `*`, `?` or `[` make it a pattern the shell expands. */
  glob: boolean
  /** As written in the command. */
  raw: string
  /**
   * A literal path as written: no glob, brace, `$VAR`, `~`, `$(...)` or
   * backticks. Only such paths may be skipped by alwaysAllow, and only they
   * can be reported "not found" with confidence.
   */
  plain: boolean
}

/** One `cd` on the way to where a command runs. */
export type CdStep = {
  dir: Word
  /**
   * True when the command runs even if this `cd` fails (`cd x; rm ...`),
   * so it then runs where the shell already was.
   */
  soft: boolean
}

export type Kind =
  | 'rm'
  | 'find-delete'
  | 'xargs-rm'
  | 'git-clean'
  | 'git-reset-hard'
  | 'git-discard'
  | 'git-push-force'
  | 'git-branch-delete'
  | 'git-worktree-remove'
  | 'redirect'

export type GitInfo =
  /** `forces`: 2 for `-ff`, which also removes nested git repositories. */
  | { sub: 'clean'; flags: string[]; forces: number; excludes: string[]; paths: Word[] }
  | { sub: 'reset'; ref?: Word }
  | {
      sub: 'discard'
      /** `all`: every uncommitted change; `maybe-ref`: `git checkout x`, a branch or a path. */
      mode: 'all' | 'paths' | 'maybe-ref'
      source?: Word
      /** True when the files come back from the index, so staged work survives. */
      fromIndex: boolean
      paths: Word[]
    }
  | { sub: 'push'; remote?: Word; refspecs: Word[]; isWholeRepo: boolean }
  | { sub: 'branch'; names: Word[] }
  | { sub: 'worktree'; paths: Word[] }

export type Finding = {
  kind: Kind
  /** The command's own text, for the person to read. */
  label: string
  /** The `cd`s between the session's directory and where it runs. */
  cd: CdStep[]
  /** What it acts on: rm operands, find start points, the redirect's file. */
  targets: Word[]
  isSudo: boolean
  git?: GitInfo
  /** For find: a read-only argv that lists what it would delete. */
  findListing?: string[]
  /** Why it cannot be measured, when that is plain from the text alone. */
  unknown?: string
  /**
   * The whole command is this one simple command and this redirect is all it
   * does that we see: no `&&`, `||`, `;`, `|`, `&`, newline, subshell,
   * `$(...)` or unquoted here-doc. Only then can "the target does not exist"
   * be judged before anything runs.
   */
  isSole?: boolean
}

export type ClassifyEnv = { home?: string }

/** How deep `$(...)`, `bash -c` and `eval` may nest before we stop looking. */
const MAX_DEPTH = 6

export function classify(command: string, env: ClassifyEnv = {}): Finding[] {
  const out: Finding[] = []
  const seq = parse(command)
  walk(seq, command, [], new Map(), env, out, 0)
  const only = out[0]
  if (out.length === 1 && only?.kind === 'redirect' && isSoleCommand(seq)) only.isSole = true
  return out
}

/** One simple command, nothing before or after it, nothing running inside it. */
function isSoleCommand(seq: Seq): boolean {
  const item = seq[0]
  if (seq.length !== 1 || !item || item.kind !== 'simple' || (item.op !== '' && item.op !== ';')) return false
  const words = [...item.words, ...item.redirs.flatMap(r => (r.target ? [r.target] : []))]
  if (words.some(w => w.parts.some(p => p.t === 'sub'))) return false
  if (item.redirs.some(r => (r.op === '<<' || r.op === '<<-') && !r.isQuotedDoc)) return false
  return item.redirs.filter(r => r.op === '>' || r.op === '>|' || r.op === '&>' || r.op === '>&').length === 1
}

type Vars = Map<string, string | undefined>

function walk(seq: Seq, src: string, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): CdStep[] {
  let steps = cd
  seq.forEach((item, index) => {
    const before = seq[index - 1]?.op ?? ''
    // A pipeline part and a `&` command run in a subshell: their `cd` stays there.
    const isPiped = item.op === '|' || item.op === '|&' || item.op === '&' || before === '|' || before === '|&'
    if (item.kind === 'group') {
      const after = walk(item.body, src, steps, vars, env, out, depth)
      redirects(item.redirs, item, src, steps, vars, env, out, depth)
      if (!item.subshell && !isPiped) steps = after
      return
    }
    const next = simple(item, src, steps, vars, env, out, depth)
    if (!isPiped) steps = next
  })
  return steps
}

const RESERVED = new Set(['if', 'then', 'else', 'elif', 'fi', 'do', 'done', 'while', 'until', 'esac', '!', 'time', '{', '}'])
const HEADERS = new Set(['for', 'select', 'case', 'function'])
const SHELLS = new Set(['bash', 'sh', 'zsh', 'dash', 'ksh'])

/** Classifies one simple command; returns the `cd` steps after it. */
function simple(item: Item & { kind: 'simple' }, src: string, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): CdStep[] {
  const label = src.slice(item.start, item.end).trim()
  const words = item.words.flatMap(w => resolveAll(w, src, vars, env))
  // Commands inside the words run first, wherever the shell is now.
  for (const w of item.words) subs(w, cd, vars, env, out, depth)
  // Inside `[[ ... ]]` a `>` compares two strings; it writes no file.
  const isTest = words[0]?.known === true && words[0].text === '[['
  if (!isTest) redirects(item.redirs, item, src, cd, vars, env, out, depth)

  let argv = words
  while (argv[0] && RESERVED.has(argv[0].text) && argv[0].known) argv = argv.slice(1)
  // `function f { body }`: the body is a command like any other.
  if (argv[0]?.known && argv[0].text === 'function') {
    argv = argv.slice(2)
    while (argv[0]?.known && (argv[0].text === '{' || argv[0].text === '()')) argv = argv.slice(1)
  }
  const head = argv[0]
  if (!head || !head.known) return cd
  if (HEADERS.has(head.text)) return cd

  // Assignments alone set shell variables; before a command they are its env.
  const firstCommand = argv.findIndex(w => !isAssignment(w))
  if (firstCommand === -1 || ['export', 'local', 'declare', 'readonly', 'typeset'].includes(head.text)) {
    for (const w of argv) {
      if (!isAssignment(w)) continue
      const name = w.raw.slice(0, w.raw.indexOf('='))
      vars.set(name, w.known ? w.text.slice(w.text.indexOf('=') + 1) : undefined)
    }
    return cd
  }
  argv = argv.slice(firstCommand)

  const peeled = peel(argv)
  argv = peeled.argv
  const program = argv[0]
  if (!program || !program.known) return cd
  const name = base(program.text)
  const steps = [...cd, ...peeled.cd]
  const finding = (kind: Kind, rest: Partial<Finding>): void => {
    out.push({ kind, label, cd: steps, targets: [], isSudo: peeled.isSudo, ...rest })
  }

  if (name === 'cd' || name === 'pushd') {
    const operand = argv.slice(1).find(w => !(w.known && /^(-[LPe@]+|--)$/.test(w.text)))
    const dir = operand ?? { text: env.home ?? '', known: env.home !== undefined, glob: false, raw: '~', plain: false }
    if (dir.known && dir.text === '-') return [...cd, { dir: { ...dir, known: false }, soft: false }]
    return [...cd, { dir, soft: item.op !== '&&' }]
  }
  if (name === 'popd') return [...cd, { dir: { text: '', known: false, glob: false, raw: 'popd', plain: false }, soft: false }]

  if (peeled.viaXargs && name === 'rm') {
    finding('xargs-rm', { unknown: 'it deletes whatever the command before it prints' })
    return cd
  }
  if (SHELLS.has(name) && depth < MAX_DEPTH) {
    const script = shellScript(argv)
    if (script?.known) walk(parse(script.text), script.text, steps, new Map(vars), env, out, depth + 1)
    return cd
  }
  if (name === 'eval' && depth < MAX_DEPTH) {
    const text = argv.slice(1).map(w => w.text).join(' ')
    if (argv.slice(1).every(w => w.known)) walk(parse(text), text, steps, new Map(vars), env, out, depth + 1)
    return cd
  }
  if (name === 'rm') {
    const rm = parseRm(argv)
    if (rm.isRecursive && rm.operands.length > 0) finding('rm', { targets: rm.operands })
  } else if (name === 'find') {
    const found = parseFind(argv)
    if (found) finding('find-delete', found)
  } else if (name === 'git') {
    const git = parseGit(argv, peeled.viaXargs)
    if (git) {
      const unknown = peeled.viaXargs ? 'more arguments come from the command before it' : git.finding.unknown
      out.push({ label, cd: [...steps, ...git.cd], targets: [], isSudo: peeled.isSudo, ...git.finding, ...(unknown ? { unknown } : {}) })
    }
  }
  return cd
}

function redirects(redirs: Redir[], item: Item, src: string, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): void {
  for (const r of redirs) {
    if (!r.target || r.target.parts.length === 0) continue
    subs(r.target, cd, vars, env, out, depth)
    const overwrites = r.op === '>' || r.op === '>|' || r.op === '&>' || r.op === '>&'
    if (!overwrites) continue
    const target = resolve(r.target, src, vars, env)
    if (target.known && (target.text.startsWith('/dev/') || target.text === '')) continue
    out.push({
      kind: 'redirect',
      label: src.slice(item.start, item.end).trim(),
      cd,
      targets: [target],
      isSudo: false,
      ...(target.known ? {} : { unknown: `it writes to ${target.raw}, which is only known when it runs` }),
    })
  }
}

/** Walks the commands a word runs inside it (`$(...)`, backticks). */
function subs(w: RawWord, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): void {
  if (depth >= MAX_DEPTH) return
  for (const p of w.parts) {
    if (p.t === 'sub') walk(parse(p.src), p.src, cd, new Map(vars), env, out, depth + 1)
  }
}

// ---------------------------------------------------------------- words

function resolve(w: RawWord, src: string, vars: Vars, env: ClassifyEnv): Word {
  let text = ''
  let known = true
  let glob = false
  let plain = true
  w.parts.forEach((p: Part, index) => {
    if (p.t === 'lit') {
      let s = p.s
      if (index === 0 && !p.quoted && s.startsWith('~')) {
        plain = false
        const user = /^~([^/]*)/.exec(s)?.[1] ?? ''
        if (user === '' && env.home !== undefined) s = env.home + s.slice(1)
        else known = false
      }
      if (!p.quoted && /[*?[]/.test(s)) glob = true
      // An unquoted brace may expand (or be refused) by the shell: not a plain path.
      if (!p.quoted && /[{}]/.test(s)) plain = false
      text += s
    } else if (p.t === 'var') {
      plain = false
      const value = vars.has(p.name) ? vars.get(p.name) : p.name === 'HOME' ? env.home : undefined
      // Unquoted, bash splits the value on spaces and globs it: one word no more.
      if (value === undefined || (!p.quoted && /[\s*?[]/.test(value))) known = false
      else text += value
    } else {
      plain = false
      known = false
    }
  })
  return { text, known, glob, raw: src.slice(w.start, w.end), plain: plain && !glob }
}

export function literalWord(text: string): Word {
  return { text, known: true, glob: false, raw: text, plain: true }
}

/** Resolves a word, expanding braces (`{a,b}`, `{1..3}`) the way the shell would first. */
function resolveAll(w: RawWord, src: string, vars: Vars, env: ClassifyEnv): Word[] {
  const only = w.parts.length === 1 ? w.parts[0] : undefined
  // Bash does not brace-expand an assignment (`X={a,b}`), so neither do we.
  const isBraced = only?.t === 'lit' && !only.quoted && /\{[^{}]*(,|\.\.)[^{}]*\}/.test(only.s) && !/^[A-Za-z_][A-Za-z0-9_]*=/.test(only.s)
  if (!isBraced || only?.t !== 'lit') return [resolve(w, src, vars, env)]
  const expanded = braces(only.s)
  const raw = src.slice(w.start, w.end)
  // Past the cap the word is unknown, so it is held, never cut short.
  if (!expanded) return [{ text: only.s, known: false, glob: false, raw, plain: false }]
  return expanded.map(s => ({ ...resolve({ ...w, parts: [{ t: 'lit', s, quoted: false }] }, src, vars, env), plain: false }))
}

/** Most words one brace expression may become, and most nested groups, before it counts as unknown. */
const BRACE_CAP = 256
const BRACE_GROUPS = 8

/**
 * Brace expansion with bounded work: comma lists and `{1..9}` / `{a..e}`
 * ranges, generated one at a time; undefined once past the cap.
 */
export function braces(s: string): string[] | undefined {
  const out: string[] = []
  const expand = (text: string, depth: number): boolean => {
    if (depth > BRACE_GROUPS) return false
    const group = braceGroup(text)
    if (!group) {
      out.push(text)
      return out.length <= BRACE_CAP
    }
    if (group.alternatives === undefined) return false
    for (const alternative of group.alternatives) {
      if (!expand(group.head + alternative + group.tail, depth + 1)) return false
    }
    return true
  }
  return expand(s, 0) ? out : undefined
}

/** The first `{...}` that expands: its alternatives (undefined: too many), and what is around it. */
function braceGroup(s: string): { head: string; tail: string; alternatives: string[] | undefined } | undefined {
  for (let open = s.indexOf('{'); open !== -1; open = s.indexOf('{', open + 1)) {
    let depth = 0
    const commas: number[] = []
    for (let j = open; j < s.length; j++) {
      if (s[j] === '{') depth++
      else if (s[j] === '}') depth--
      else if (s[j] === ',' && depth === 1) commas.push(j)
      if (depth !== 0) continue
      const head = s.slice(0, open)
      const tail = s.slice(j + 1)
      const body = s.slice(open + 1, j)
      if (commas.length > 0) {
        const cuts = [open, ...commas, j]
        return { head, tail, alternatives: cuts.slice(1).map((cut, k) => s.slice((cuts[k] ?? open) + 1, cut)) }
      }
      const range = /^(-?\d+|[a-zA-Z])\.\.(-?\d+|[a-zA-Z])$/.exec(body)
      if (range) return { head, tail, alternatives: sequence(range[1] ?? '', range[2] ?? '') }
      break
    }
  }
  return undefined
}

function sequence(from: string, to: string): string[] | undefined {
  const isNumber = /\d/.test(from)
  if (isNumber !== /\d/.test(to)) return undefined
  const a = isNumber ? Number(from) : from.charCodeAt(0)
  const b = isNumber ? Number(to) : to.charCodeAt(0)
  if (Math.abs(b - a) >= BRACE_CAP) return undefined
  const step = a <= b ? 1 : -1
  const out: string[] = []
  for (let n = a; step > 0 ? n <= b : n >= b; n += step) out.push(isNumber ? String(n) : String.fromCharCode(n))
  return out
}

function isAssignment(w: Word): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*=/.test(w.raw)
}

export function base(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

// ---------------------------------------------------------------- prefixes

type Peeled = { argv: Word[]; cd: CdStep[]; isSudo: boolean; viaXargs: boolean }

/** Options of each prefix command that take a value of their own. */
const VALUED: Record<string, readonly string[]> = {
  sudo: ['-u', '-g', '-C', '-D', '-h', '-p', '-r', '-t', '-T', '-U', '--user', '--group', '--chdir'],
  doas: ['-u', '-C'],
  env: ['-u', '-C', '-S', '-P', '--unset', '--chdir', '--split-string'],
  nice: ['-n', '--adjustment'],
  ionice: ['-c', '-n', '-p', '-P', '-u', '--class', '--classdata'],
  stdbuf: ['-i', '-o', '-e', '--input', '--output', '--error'],
  timeout: ['-s', '-k', '--signal', '--kill-after'],
  exec: ['-a'],
  xargs: ['-E', '-I', '-L', '-n', '-P', '-s', '-d', '-a', '--arg-file', '--delimiter', '--max-args', '--max-procs', '--max-chars', '--max-lines', '--replace', '--eof'],
}
const PREFIXES = new Set([...Object.keys(VALUED), 'nohup', 'time', 'command', 'builtin', 'chronic', 'caffeinate', 'unbuffer'])

/** Strips `sudo`, `env X=1`, `nohup`, `xargs` and kin down to the real program. */
function peel(words: Word[]): Peeled {
  let argv = words
  const cd: CdStep[] = []
  let isSudo = false
  let viaXargs = false
  for (let guard = 0; guard < 8; guard++) {
    const head = argv[0]
    if (!head?.known) break
    const name = base(head.text)
    if (!PREFIXES.has(name)) break
    if (name === 'command' && argv.slice(1).some(w => w.text === '-v' || w.text === '-V')) return { argv: [], cd, isSudo, viaXargs }
    if (name === 'sudo' || name === 'doas') isSudo = true
    if (name === 'xargs') viaXargs = true
    const valued = VALUED[name] ?? []
    let k = 1
    while (k < argv.length) {
      const w = argv[k]
      if (!w?.known) break
      if (w.text === '--') {
        k++
        break
      }
      if (name === 'env' && isAssignment(w)) {
        k++
        continue
      }
      if (!w.text.startsWith('-') || w.text === '-') break
      const flag = w.text.split('=')[0] ?? ''
      const takesValue = valued.includes(flag) && !w.text.includes('=')
      const value = takesValue ? argv[k + 1] : w.text.includes('=') ? { ...w, text: w.text.slice(w.text.indexOf('=') + 1) } : undefined
      if ((name === 'env' && (flag === '-C' || flag === '--chdir')) || (name === 'sudo' && (flag === '-D' || flag === '--chdir'))) {
        if (value) cd.push({ dir: value, soft: false })
      }
      k += takesValue ? 2 : 1
    }
    // `timeout 10 cmd`: the duration comes before the command.
    if (name === 'timeout' && argv[k]?.known && /^[\d.]+[smhd]?$/.test(argv[k]?.text ?? '')) k++
    argv = argv.slice(k)
    // `sudo FOO=1 rm ...`: variables set for the command, not the command.
    while (argv[0] && isAssignment(argv[0])) argv = argv.slice(1)
  }
  return { argv, cd, isSudo, viaXargs }
}

/** `bash -c 'script'`: the script, or undefined when there is no `-c`. */
function shellScript(argv: Word[]): Word | undefined {
  let hasC = false
  for (let k = 1; k < argv.length; k++) {
    const w = argv[k]
    if (!w) break
    if (w.known && /^-[a-zA-Z]+$/.test(w.text)) {
      if (w.text.includes('c')) hasC = true
      if (w.text === '-o' || w.text === '-O') k++
      continue
    }
    if (w.known && w.text.startsWith('--')) continue
    return hasC ? w : undefined
  }
  return undefined
}

// ---------------------------------------------------------------- rm

export function parseRm(argv: Word[]): { isRecursive: boolean; operands: Word[] } {
  let isRecursive = false
  let isEnd = false
  const operands: Word[] = []
  for (const w of argv.slice(1)) {
    const t = w.text
    if (!isEnd && w.known && t === '--') isEnd = true
    else if (!isEnd && w.known && t.startsWith('--')) {
      // GNU takes any unique prefix of a long option: --rec, --recur.
      if (t.length >= 3 && '--recursive'.startsWith(t)) isRecursive = true
    } else if (!isEnd && w.known && t.startsWith('-') && t.length > 1) {
      if (/[rR]/.test(t)) isRecursive = true
    } else operands.push(w)
  }
  return { isRecursive, operands }
}

// ---------------------------------------------------------------- find

const FIND_LEADING = new Set(['-H', '-L', '-P', '-E', '-X', '-s', '-x', '-d'])
const FIND_VALUED = new Set([
  '-name', '-iname', '-path', '-ipath', '-wholename', '-iwholename', '-regex', '-iregex', '-lname', '-ilname',
  '-type', '-xtype', '-size', '-perm', '-user', '-group', '-uid', '-gid', '-maxdepth', '-mindepth', '-mtime',
  '-atime', '-ctime', '-mmin', '-amin', '-cmin', '-newer', '-anewer', '-cnewer', '-samefile', '-inum', '-links',
  '-fstype', '-used', '-context', '-printf', '-fprint', '-fprint0', '-fls', '-regextype', '-newermt', '-newerct',
  '-newerat', '-newerBt',
])
const FIND_EXEC = new Set(['-exec', '-execdir', '-ok', '-okdir'])
/**
 * Predicates that write files or run commands. Never copied into a measuring
 * command: a find holding one is held unmeasured (GNU find opens -fprint
 * files for writing while it parses, before it runs anything).
 */
export const FIND_WRITES = new Set(['-delete', '-exec', '-execdir', '-ok', '-okdir', '-fprint', '-fprint0', '-fprintf', '-fls'])
/** Tests whose meaning differs between the system find and the shell's own (bfs, GNU). */
const FIND_UNPORTABLE = new Set(['-regex', '-iregex', '-regextype', '-readable', '-writable', '-executable'])
/** Actions that write or print on their own: a listing re-run would not be clean. */
const FIND_SIDE_EFFECTS = new Set(['-exec', '-execdir', '-ok', '-okdir', '-fprint', '-fprint0', '-fprintf', '-fls', '-delete', '-print', '-print0', '-printf', '-ls'])

export function parseFind(argv: Word[]): Partial<Finding> | undefined {
  const args = argv.slice(1)
  let k = 0
  const leading: string[] = []
  while (k < args.length) {
    const t = args[k]?.text ?? ''
    if (FIND_LEADING.has(t) || /^-O\d$/.test(t)) {
      leading.push(t)
      k++
    } else if (t === '-D' || t === '-f') {
      leading.push(t, args[k + 1]?.text ?? '')
      k += 2
    } else break
  }
  const starts: Word[] = []
  while (k < args.length) {
    const t = args[k]?.text ?? ''
    if (args[k]?.known && (t.startsWith('-') || t === '(' || t === '!' || t === ')' || t === ',')) break
    const w = args[k]
    if (w) starts.push(w)
    k++
  }
  const expr = args.slice(k)

  // Scan the expression, skipping the values of tests that take one.
  let deletes = false
  let usesDelete = false
  const listing: string[] = []
  const isKnown = expr.every(w => w.known) && starts.every(w => w.known && !w.glob)
  let isListable = true
  let isPortable = true
  for (let j = 0; j < expr.length; j++) {
    const t = expr[j]?.text ?? ''
    // Writers first: -fprint takes a value, but must never reach the listing.
    if (t === '-fprint' || t === '-fprint0' || t === '-fprintf' || t === '-fls') {
      isListable = false
      j += t === '-fprintf' ? 2 : 1
      continue
    }
    if (FIND_UNPORTABLE.has(t)) isPortable = false
    if (FIND_VALUED.has(t)) {
      listing.push(t, expr[j + 1]?.text ?? '')
      j++
      continue
    }
    if (t === '-delete') {
      deletes = true
      usesDelete = true
      listing.push('-print0')
      continue
    }
    if (FIND_EXEC.has(t)) {
      let end = j + 1
      while (end < expr.length && expr[end]?.text !== ';' && expr[end]?.text !== '+') end++
      // `-exec sudo rm`, `-exec env rm`: peel the same prefixes as a command line.
      const command = peel(expr.slice(j + 1, end)).argv
      const program = command[0]?.known ? base(command[0].text) : ''
      if (program === 'rm') {
        deletes = true
        listing.push('-print0')
      } else if (SHELLS.has(program) || program === 'eval' || program === 'xargs' || !command[0]?.known) {
        // A shell or a run-time program could delete anything: held unmeasured.
        deletes = true
        isListable = false
      } else {
        isListable = false
      }
      j = end
      continue
    }
    if (FIND_SIDE_EFFECTS.has(t)) isListable = false
    listing.push(t)
  }
  if (!deletes) return undefined
  const from = starts.length > 0 ? starts : [{ text: '.', known: true, glob: false, raw: '.', plain: true }]
  if (!isKnown) return { targets: from, unknown: 'it names paths that are only known when it runs' }
  if (!isListable) return { targets: from, unknown: 'its find expression does more than delete, so it was not re-run to look' }
  if (!isPortable) return { targets: from, unknown: 'it uses a find test the system find reads differently from the shell' }
  // -delete turns on -depth, which also switches -prune off: list the same way.
  return { targets: from, findListing: [...leading, ...from.map(w => w.text), ...(usesDelete ? ['-depth'] : []), ...listing] }
}

// ---------------------------------------------------------------- git

/** Options of a branch switch that cannot discard anything. */
const SWITCH_FLAGS = new Set(['-q', '--quiet', '-t', '--track', '--no-track', '--detach', '--progress', '--no-progress', '--guess', '--no-guess'])

type GitParsed = { cd: CdStep[]; finding: Pick<Finding, 'kind' | 'git' | 'unknown'> }

function shortFlags(t: string): string {
  return /^-[A-Za-z]+$/.test(t) ? t.slice(1) : ''
}

export function parseGit(argv: Word[], viaXargs = false): GitParsed | undefined {
  const cd: CdStep[] = []
  let k = 1
  let unknown: string | undefined
  while (k < argv.length) {
    const w = argv[k]
    if (!w?.known || !w.text.startsWith('-')) break
    if (w.text === '-C') {
      const dir = argv[k + 1]
      if (dir) cd.push({ dir, soft: false })
      k += 2
    } else if (w.text === '-c' || w.text === '--git-dir' || w.text === '--work-tree' || w.text === '--namespace') {
      if (w.text !== '-c') unknown = 'it points git at another repository'
      k += 2
    } else {
      if (w.text.startsWith('--git-dir=') || w.text.startsWith('--work-tree=')) unknown = 'it points git at another repository'
      k++
    }
  }
  const sub = argv[k]
  if (!sub?.known) return undefined
  const rest = argv.slice(k + 1)
  const parsed = gitSub(sub.text, rest, viaXargs)
  if (!parsed) return undefined
  return { cd, finding: unknown ? { ...parsed, unknown } : parsed }
}

function gitSub(sub: string, rest: Word[], viaXargs: boolean): Pick<Finding, 'kind' | 'git'> | undefined {
  const positionals: Word[] = []
  const after: Word[] = []
  let isEnd = false
  const flags: string[] = []
  for (let j = 0; j < rest.length; j++) {
    const w = rest[j]
    if (!w) continue
    if (isEnd) after.push(w)
    else if (w.known && w.text === '--') isEnd = true
    else if (w.known && w.text.startsWith('-') && w.text !== '-') {
      flags.push(w.text)
      // Options whose value is a separate word.
      const valued: Record<string, readonly string[]> = {
        clean: ['-e', '--exclude'],
        checkout: ['-b', '-B', '-c', '-C', '--orphan', '--conflict'],
        restore: ['-s', '--source'],
        push: ['-o', '--push-option', '--repo', '--receive-pack', '--exec'],
        branch: ['-u', '--set-upstream-to', '--contains', '--no-contains', '--merged', '--no-merged', '--points-at', '--format', '--sort'],
      }
      if ((valued[sub] ?? []).includes(w.text)) {
        const value = rest[j + 1]
        if (value) flags.push(value.text)
        j++
      }
    } else positionals.push(w)
  }
  const has = (...names: string[]) => flags.some(f => names.includes(f))
  const hasShort = (ch: string) => flags.some(f => shortFlags(f).includes(ch))

  if (sub === 'clean') {
    const forces = flags.reduce((n, f) => n + (f === '--force' ? 1 : (shortFlags(f).match(/f/g) ?? []).length), 0)
    if (forces === 0 || hasShort('n') || has('--dry-run')) return undefined
    const keep = ['d', 'x', 'X'].filter(hasShort)
    const excludes: string[] = []
    flags.forEach((f, j) => {
      if (f === '-e' || f === '--exclude') excludes.push(flags[j + 1] ?? '')
      else if (f.startsWith('--exclude=')) excludes.push(f.slice('--exclude='.length))
    })
    return { kind: 'git-clean', git: { sub: 'clean', flags: keep, forces, excludes, paths: [...positionals, ...after] } }
  }
  if (sub === 'worktree') {
    // `git worktree remove --force` deletes the worktree folder, uncommitted work and all.
    const [action, ...targets] = [...positionals, ...after]
    if (action?.text !== 'remove' || !(has('--force') || hasShort('f'))) return undefined
    return { kind: 'git-worktree-remove', git: { sub: 'worktree', paths: targets } }
  }
  if (sub === 'reset') {
    if (!has('--hard')) return undefined
    const ref = positionals[0]
    return { kind: 'git-reset-hard', git: ref ? { sub: 'reset', ref } : { sub: 'reset' } }
  }
  if (sub === 'checkout') {
    const isForced = has('-f', '--force')
    if (has('-p', '--patch')) return undefined
    if (!isForced && has('-b', '-B', '-c', '-C', '--orphan')) return undefined
    const discard = (mode: 'all' | 'paths' | 'maybe-ref', paths: Word[], source?: Word): Pick<Finding, 'kind' | 'git'> => ({
      kind: 'git-discard',
      git: { sub: 'discard', mode, paths, fromIndex: source === undefined, ...(source ? { source } : {}) },
    })
    if (isEnd) {
      if (after.length > 0) return discard('paths', after, positionals[0])
      return isForced ? discard('all', []) : undefined
    }
    if (isForced) return discard('all', [])
    const [first, ...others] = positionals
    if (!first || (first.known && first.text === '-')) return undefined
    if (others.length > 0) return discard('paths', others, first)
    // Only a bare `git checkout <plain name>` may turn out to be a branch switch
    // (the measurer asks git). Any other option, or a name that is not a plain
    // token, is taken as paths and held.
    const isBare = flags.every(f => SWITCH_FLAGS.has(f.split('=')[0] ?? ''))
    const isPath = !isBare || !first.plain || first.text === '.' || first.text.startsWith('./') || first.text.startsWith(':/')
    return discard(isPath ? 'paths' : 'maybe-ref', [first])
  }
  if (sub === 'restore') {
    const staged = hasShort('S') || has('--staged')
    const worktree = hasShort('W') || has('--worktree')
    if ((staged && !worktree) || hasShort('p') || has('--patch')) return undefined
    const paths = [...positionals, ...after]
    if (paths.length === 0) return undefined
    const sourceAt = flags.findIndex(f => f === '-s' || f === '--source')
    const sourceText = sourceAt >= 0 ? flags[sourceAt + 1] : flags.find(f => f.startsWith('--source='))?.slice('--source='.length)
    const source = sourceText !== undefined ? literalWord(sourceText) : staged ? literalWord('HEAD') : undefined
    return { kind: 'git-discard', git: { sub: 'discard', mode: 'paths', paths, fromIndex: source === undefined, ...(source ? { source } : {}) } }
  }
  if (sub === 'switch') {
    if (!has('--discard-changes', '-f', '--force')) return undefined
    return { kind: 'git-discard', git: { sub: 'discard', mode: 'all', paths: [], fromIndex: false } }
  }
  if (sub === 'push') {
    const name = (f: string) => f.split('=')[0] ?? ''
    // git takes a unique prefix of a long option: --force-with is the lease.
    const isMirror = flags.some(f => name(f) === '--mirror')
    const isForced = has('--force') || hasShort('f') || isMirror || [...positionals, ...after].slice(1).some(w => w.text.startsWith('+'))
    // A lease guards only a push that is not also forced: `--force` (or -f,
    // a `+refspec`, --mirror) switches the lease off, so it is held.
    if (!isForced || has('--dry-run') || hasShort('n')) return undefined
    const isWholeRepo = isMirror || has('--all', '--branches', '--tags')
    const [remote, ...refspecs] = [...positionals, ...after]
    return { kind: 'git-push-force', git: { sub: 'push', refspecs, isWholeRepo, ...(remote ? { remote } : {}) } }
  }
  if (sub === 'branch') {
    const isDelete = hasShort('d') || hasShort('D') || has('--delete')
    const isForced = hasShort('D') || hasShort('f') || has('--force')
    if (!isDelete || !isForced || hasShort('r') || has('--remotes')) return undefined
    // Names after `--` are names too: `git branch -D -- feature`.
    const names = [...positionals, ...after]
    return names.length > 0 || viaXargs ? { kind: 'git-branch-delete', git: { sub: 'branch', names } } : undefined
  }
  return undefined
}

export { literal }

files.hooks/plan.ts:
// The pure part of mulligan: from what the classifier found in a command, what
// a snapshot must hold so /mulligan can put the project back; and the words.
//
// A positive list of shapes, never "everything not matched is safe": the
// classifier names the commands that destroy files (rm, find -delete, xargs
// rm, git clean, git reset --hard, git checkout or restore over changes,
// git worktree remove, a redirect over a file). Pushes and branch deletions
// touch no file here and take no snapshot.

import type { CdStep, Finding, Word } from './classify'
import { join, normalize, within } from './paths'

/** What one snapshot holds. */
export type Scope = {
  /** Every file under the project (git: tracked changes and untracked files). */
  isTree: boolean
  /** git: the tracked files' state, through `git stash create` (HEAD when nothing changed). */
  isTracked: boolean
  /** git: untracked files that are not ignored. */
  isUntracked: boolean
  /** Paths under the project the command acts on, absolute, none inside another. */
  paths: string[]
}

export type Plan = {
  scope: Scope
  /** Targets outside the project, which no snapshot covers. */
  outside: string[]
  /** What the snapshot leaves out, in words (ignored files under git clean -x). */
  notes: string[]
}

export const EMPTY_SCOPE: Scope = { isTree: false, isTracked: false, isUntracked: false, paths: [] }

/** True when the scope holds nothing to save. */
export function isEmpty(scope: Scope): boolean {
  return !scope.isTree && !scope.isTracked && !scope.isUntracked && scope.paths.length === 0
}

/** Where a finding runs: the shell's directory through its `cd`s, or undefined when a `cd` is unknown ahead. */
export function whereItRuns(cwd: string, steps: readonly CdStep[]): string | undefined {
  let dir = cwd
  for (const step of steps) {
    if (!step.dir.known) return undefined
    dir = join(dir, step.dir.text)
  }
  return dir
}

/**
 * The part of a path written before its first pattern: `build/*` is `build`, `**` is nothing.
 * Undefined when the word holds an expansion nobody can know ahead.
 */
export function staticPart(word: Word): string | undefined {
  if (!word.known) return undefined
  if (!word.glob) return word.text
  const segments: string[] = []
  for (const segment of word.text.split('/')) {
    if (/[*?[{]/.test(segment)) break
    segments.push(segment)
  }
  return segments.join('/')
}

/**
 * What to save before `findings` run from the shell's directory `cwd`, in a project at `root`.
 * Null when nothing in the command touches files (no finding, or only pushes and branch deletes).
 */
export function planFor(findings: readonly Finding[], cwd: string, root: string, isGit: boolean): Plan | null {
  const scope: Scope = { ...EMPTY_SCOPE, paths: [] }
  const outside: string[] = []
  const notes: string[] = []
  let isFiles = false
  const add = (dir: string | undefined, target: Word) => {
    const part = dir === undefined ? undefined : staticPart(target)
    if (dir === undefined || part === undefined || part === '') {
      scope.isTree = true // where or what is only known when it runs: save the whole project
      return
    }
    const path = join(dir, part)
    if (!within(root, path)) outside.push(path)
    else if (path === normalize(root)) scope.isTree = true
    else scope.paths.push(path)
  }
  for (const f of findings) {
    const dir = whereItRuns(cwd, f.cd)
    switch (f.kind) {
      case 'rm':
      case 'find-delete':
      case 'redirect':
        isFiles = true
        if (f.targets.length === 0) scope.isTree = true
        for (const target of f.targets) add(dir, target)
        break
      case 'xargs-rm':
        isFiles = true
        scope.isTree = true // it deletes whatever the command before it prints
        break
      case 'git-worktree-remove':
        isFiles = true
        for (const target of f.git?.sub === 'worktree' ? f.git.paths : []) add(dir, target)
        break
      case 'git-clean':
        isFiles = true
        if (dir !== undefined && !within(root, dir)) outside.push(dir) // git -C another repository
        else if (isGit) scope.isUntracked = true
        else scope.isTree = true
        if (f.git?.sub === 'clean' && f.git.flags.some(flag => /x/i.test(flag.replace(/^--?/, '')))) {
          notes.push('ignored files (git clean -x) are not saved')
        }
        break
      case 'git-reset-hard':
      case 'git-discard':
        isFiles = true
        if (dir !== undefined && !within(root, dir)) outside.push(dir)
        else if (isGit) scope.isTracked = true
        else scope.isTree = true
        break
      case 'git-push-force':
      case 'git-branch-delete':
        break // no file in the project changes
    }
  }
  if (!isFiles) return null
  if (scope.isTree) {
    scope.paths = []
    if (isGit) {
      scope.isTracked = true
      scope.isUntracked = true
    }
  }
  scope.paths = outermost(scope.paths)
  return { scope, outside: [...new Set(outside)], notes }
}

/** The whole project, for the person's own `always` pattern. */
export function treePlan(isGit: boolean): Plan {
  return { scope: { isTree: true, isTracked: isGit, isUntracked: isGit, paths: [] }, outside: [], notes: [] }
}

/** Paths with every one inside another dropped: `build` covers `build/x`. */
export function outermost(paths: readonly string[]): string[] {
  const sorted = [...new Set(paths)].sort()
  return sorted.filter(path => !sorted.some(other => other !== path && within(other, path)))
}

/** A path as the person reads it: relative to the project, else as it is. */
export function shown(path: string, root: string): string {
  if (path === root) return '.'
  return within(root, path) ? path.slice(root === '/' ? 1 : root.length + 1) : path
}

/** What a snapshot holds, in a few words: "build, dist", "tracked changes and untracked files", "the project". */
export function scopeWords(scope: Scope, root: string): string {
  if (scope.isTree) return 'the project'
  const parts: string[] = []
  if (scope.isTracked) parts.push('tracked changes')
  if (scope.isUntracked) parts.push('untracked files')
  if (scope.paths.length > 0) {
    const names = scope.paths.map(path => shown(path, root))
    parts.push(names.length <= 3 ? names.join(', ') : `${names.slice(0, 3).join(', ')} and ${names.length - 3} more`)
  }
  return parts.join(' and ')
}

/** One line for a drawing: whitespace runs as one space, at most `max` characters. */
export function oneLine(text: string, max: number): string {
  const flat = text.replace(/\s+/g, ' ').trim()
  return flat.length <= max ? flat : `${flat.slice(0, max - 1)}…`
}

/** Control characters and escape sequences out of anything drawn (commands and paths are Claude's). */
export function clean(text: string): string {
  return text
    .replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '')
    .replace(/\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g, '')
    .replace(/[\x00-\x09\x0b-\x1f\x7f-\x9f]/g, '�')
}

/** 12345678 bytes as "12 MB". */
export function sizeWords(bytes: number): string {
  if (bytes < 1_000) return `${bytes} B`
  if (bytes < 1_000_000) return `${Math.round(bytes / 1_000)} KB`
  return `${Math.round(bytes / 100_000) / 10} MB`
}

/** "3m ago", "2h ago", for the list. */
export function agoWords(ms: number): string {
  const minutes = Math.floor(ms / 60_000)
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.floor(minutes / 60)
  return hours < 48 ? `${hours}h ago` : `${Math.floor(hours / 24)}d ago`
}

/** FNV-1a over the project root: a short key for its folder that does not spell the path. */
export function projectKey(root: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < root.length; i++) {
    h ^= root.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  let g = 0x01000193
  for (let i = root.length - 1; i >= 0; i--) {
    g ^= root.charCodeAt(i)
    g = Math.imul(g, 0x811c9dc5) >>> 0
  }
  return h.toString(16).padStart(8, '0') + g.toString(16).padStart(8, '0')
}

/** The note Claude reads after a restore: its view of the files is stale. */
export function restoreNote(command: string, n: number): string {
  return (
    `The person restored files in this project to how they were before the command \`${oneLine(command, 200)}\` ` +
    `(mulligan snapshot ${n}). Files may differ from what you last read: re-read any file before editing it.`
  )
}

files.hooks/shell.ts:
// The same file as last-look's hooks/shell.ts, copied so this mod installs on its own.
// Keep the two in step: a fix to one is a fix to both.

// A small, forgiving shell parser: just enough of bash's grammar to see which
// commands a string runs, with which words and redirects, in which order.
//
// It never throws and always ends: on input bash would reject (an open quote,
// a stray paren) it keeps going with its best reading, because a guard that
// stops at a parse error would let the rest of the string through unread.

/** One piece of a word, as written. */
export type Part =
  | { t: 'lit'; s: string; quoted: boolean }
  /** `quoted`: inside double quotes, so the shell neither splits nor globs its value. */
  | { t: 'var'; name: string; quoted: boolean }
  /** `$( ... )`, backticks or `<( ... )`: a command of its own. */
  | { t: 'sub'; src: string }
  /** An expansion nobody can know ahead (`$1`, `$((n+1))`, `${x:-y}`). */
  | { t: 'opaque' }

export type RawWord = { parts: Part[]; start: number; end: number }

export type Redir = {
  op: string
  fd?: string
  /** The file it names; absent for a here-doc or a descriptor copy (`2>&1`). */
  target?: RawWord
  /** For a here-doc: its delimiter was quoted, so its body is plain data (no `$(...)` runs). */
  isQuotedDoc?: boolean
}

export type Simple = {
  kind: 'simple'
  words: RawWord[]
  redirs: Redir[]
  start: number
  end: number
}

export type Group = {
  kind: 'group'
  /** `( ... )` runs in a subshell; `{ ...; }` does not, so its `cd` sticks. */
  subshell: boolean
  body: Seq
  redirs: Redir[]
  start: number
  end: number
}

/** A command and the operator after it: `&&`, `||`, `;`, `|`, `&`, or ``. */
export type Item = (Simple | Group) & { op: string }
export type Seq = Item[]

const BLANK = new Set([' ', '\t', '\r'])
const ENDS_WORD = new Set([' ', '\t', '\r', '\n', ';', '&', '|', '(', ')', '<', '>'])
const REDIRECT = /^(\d*)(&>>|&>|>>|>\||>&|<<<|<<-|<<|<>|<&|>|<)/

export function parse(src: string): Seq {
  return new Parser(src).seq(false)
}

class Parser {
  private i = 0
  private heredocs: { delim: string; strip: boolean }[] = []

  constructor(private readonly src: string) {}

  seq(close: ')' | '}' | false): Seq {
    const items: Seq = []
    while (true) {
      this.blank()
      if (this.i >= this.src.length) return items
      const c = this.src[this.i]
      if (c === '\n') {
        this.newline()
        continue
      }
      if (c === ')') {
        this.i++
        if (close === ')') return items
        continue
      }
      if (c === ';' || c === '&' || c === '|') {
        this.i++
        continue
      }
      if (close === '}' && this.atWord('}')) {
        this.i++
        return items
      }
      const node = this.command()
      this.blank()
      items.push({ ...node, op: this.operator() })
    }
  }

  private command(): Simple | Group {
    const start = this.i
    if (this.src.startsWith('((', this.i)) {
      // Arithmetic `(( n > 2 ))`: its `>` compares, it redirects nothing.
      this.i = this.balanced(this.i)
      return { kind: 'simple', words: [], redirs: [], start, end: this.i }
    }
    if (this.src[this.i] === '(') {
      this.i++
      const body = this.seq(')')
      return { kind: 'group', subshell: true, body, redirs: this.redirects(), start, end: this.i }
    }
    if (this.atWord('{')) {
      this.i++
      const body = this.seq('}')
      return { kind: 'group', subshell: false, body, redirs: this.redirects(), start, end: this.i }
    }
    return this.simple()
  }

  private simple(): Simple {
    const start = this.i
    const words: RawWord[] = []
    const redirs: Redir[] = []
    while (true) {
      this.blank()
      const c = this.src[this.i]
      if (c === undefined || c === '\n' || c === ';' || c === '|' || c === ')' || c === '(') break
      if (c === '&' && this.src[this.i + 1] !== '>') break
      if ((c === '<' || c === '>') && this.src[this.i + 1] === '(') {
        words.push(this.processSub())
        continue
      }
      const redir = this.redirect()
      if (redir) {
        redirs.push(redir)
        continue
      }
      const before = this.i
      const word = this.word()
      if (this.i === before) {
        this.i++
        continue
      }
      words.push(word)
    }
    return { kind: 'simple', words, redirs, start, end: this.i }
  }

  /** Redirects after a group's closing paren or brace. */
  private redirects(): Redir[] {
    const out: Redir[] = []
    while (true) {
      this.blank()
      const redir = this.redirect()
      if (!redir) return out
      out.push(redir)
    }
  }

  private redirect(): Redir | undefined {
    const m = REDIRECT.exec(this.src.slice(this.i, this.i + 8))
    if (!m) return undefined
    const fd = m[1] === '' ? undefined : m[1]
    const op = m[2] ?? ''
    this.i += m[0].length
    this.blank()
    if (op === '<<' || op === '<<-') {
      const delim = this.word()
      this.heredocs.push({ delim: literal(delim), strip: op === '<<-' })
      return { op, fd, isQuotedDoc: delim.parts.some(p => p.t === 'lit' && p.quoted) }
    }
    const target = this.word()
    if ((op === '>&' || op === '<&') && /^(\d+|-)$/.test(literal(target))) return { op, fd }
    return { op, fd, target }
  }

  private operator(): string {
    const two = this.src.slice(this.i, this.i + 2)
    if (two === '&&' || two === '||' || two === '|&' || two === ';;') {
      this.i += 2
      return two === ';;' ? ';' : two
    }
    const c = this.src[this.i]
    if (c === ';' || c === '|' || c === '&') {
      this.i++
      return c
    }
    if (c === '\n') {
      this.newline()
      return ';'
    }
    return ''
  }

  /** Is the next word exactly `w`, unquoted and standing alone? */
  private atWord(w: string): boolean {
    if (!this.src.startsWith(w, this.i)) return false
    const after = this.src[this.i + w.length]
    return after === undefined || ENDS_WORD.has(after)
  }

  /** Spaces, tabs, line continuations and comments; never a newline. */
  private blank(): void {
    while (this.i < this.src.length) {
      const c = this.src[this.i]
      if (c !== undefined && BLANK.has(c)) this.i++
      else if (c === '\\' && this.src[this.i + 1] === '\n') this.i += 2
      else if (c === '#') {
        while (this.i < this.src.length && this.src[this.i] !== '\n') this.i++
      } else return
    }
  }

  /** Consumes a newline, then the bodies of any here-docs opened on its line. */
  private newline(): void {
    this.i++
    for (const doc of this.heredocs) {
      while (this.i < this.src.length) {
        const cut = this.src.indexOf('\n', this.i)
        const lineEnd = cut === -1 ? this.src.length : cut
        const line = this.src.slice(this.i, lineEnd)
        this.i = lineEnd + 1
        if ((doc.strip ? line.replace(/^\t+/, '') : line) === doc.delim) break
      }
    }
    this.heredocs = []
    if (this.i > this.src.length) this.i = this.src.length
  }

  private word(): RawWord {
    const start = this.i
    const parts: Part[] = []
    let lit = ''
    const flush = () => {
      if (lit !== '') parts.push({ t: 'lit', s: lit, quoted: false })
      lit = ''
    }
    while (this.i < this.src.length) {
      const c = this.src[this.i] ?? ''
      if (ENDS_WORD.has(c)) break
      if (c === '\\') {
        const next = this.src[this.i + 1]
        this.i += 2
        if (next === undefined || next === '\n') continue
        flush()
        parts.push({ t: 'lit', s: next, quoted: true })
      } else if (c === "'") {
        flush()
        const close = this.src.indexOf("'", this.i + 1)
        const end = close === -1 ? this.src.length : close
        parts.push({ t: 'lit', s: this.src.slice(this.i + 1, end), quoted: true })
        this.i = end + 1
      } else if (c === '"') {
        flush()
        this.i++
        this.doubleQuoted(parts)
      } else if (c === '$') {
        flush()
        this.dollar(parts, false)
      } else if (c === '`') {
        flush()
        parts.push({ t: 'sub', src: this.backtick() })
      } else {
        lit += c
        this.i++
      }
    }
    flush()
    if (this.i > this.src.length) this.i = this.src.length
    return { parts, start, end: this.i }
  }

  private doubleQuoted(parts: Part[]): void {
    let lit = ''
    const flush = () => {
      if (lit !== '') parts.push({ t: 'lit', s: lit, quoted: true })
      lit = ''
    }
    while (this.i < this.src.length) {
      const c = this.src[this.i] ?? ''
      if (c === '"') {
        this.i++
        break
      }
      if (c === '\\') {
        const next = this.src[this.i + 1] ?? ''
        if (next === '\n') this.i += 2
        else if ('$`"\\'.includes(next) && next !== '') {
          lit += next
          this.i += 2
        } else {
          lit += c
          this.i++
        }
      } else if (c === '$') {
        flush()
        this.dollar(parts, true)
      } else if (c === '`') {
        flush()
        parts.push({ t: 'sub', src: this.backtick() })
      } else {
        lit += c
        this.i++
      }
    }
    flush()
  }

  private dollar(parts: Part[], inQuotes: boolean): void {
    const next = this.src[this.i + 1] ?? ''
    if (next === '(') {
      if (this.src[this.i + 2] === '(') {
        this.i = this.balanced(this.i + 1)
        parts.push({ t: 'opaque' })
        return
      }
      const end = this.balanced(this.i + 1)
      parts.push({ t: 'sub', src: this.src.slice(this.i + 2, Math.max(this.i + 2, end - 1)) })
      this.i = end
    } else if (next === '{') {
      const close = this.src.indexOf('}', this.i + 2)
      const end = close === -1 ? this.src.length : close
      const inner = this.src.slice(this.i + 2, end)
      parts.push(/^[A-Za-z_][A-Za-z0-9_]*$/.test(inner) ? { t: 'var', name: inner, quoted: inQuotes } : { t: 'opaque' })
      this.i = end + 1
    } else if (/[A-Za-z_]/.test(next)) {
      const m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(this.src.slice(this.i + 1)) ?? ['']
      parts.push({ t: 'var', name: m[0], quoted: inQuotes })
      this.i += 1 + m[0].length
    } else if (/[0-9@*#?$!-]/.test(next) && next !== '') {
      parts.push({ t: 'opaque' })
      this.i += 2
    } else if (next === "'" && !inQuotes) {
      // $'...': ANSI-C quoting; the common escapes are enough here.
      let s = ''
      let j = this.i + 2
      while (j < this.src.length && this.src[j] !== "'") {
        if (this.src[j] === '\\' && j + 1 < this.src.length) {
          const e = this.src[j + 1] ?? ''
          s += e === 'n' ? '\n' : e === 't' ? '\t' : e
          j += 2
        } else s += this.src[j++]
      }
      parts.push({ t: 'lit', s, quoted: true })
      this.i = j + 1
    } else if (next === '"' && !inQuotes) {
      this.i += 2
      this.doubleQuoted(parts)
    } else {
      parts.push({ t: 'lit', s: '$', quoted: inQuotes })
      this.i++
    }
  }

  /** From an opening paren at `open`, the index just past its partner. */
  private balanced(open: number): number {
    let depth = 0
    let j = open
    while (j < this.src.length) {
      const c = this.src[j]
      if (c === '\\') j += 2
      else if (c === "'") {
        const close = this.src.indexOf("'", j + 1)
        j = close === -1 ? this.src.length : close + 1
      } else if (c === '"') {
        j++
        while (j < this.src.length && this.src[j] !== '"') j += this.src[j] === '\\' ? 2 : 1
        j++
      } else if (c === '(') {
        depth++
        j++
      } else if (c === ')') {
        depth--
        j++
        if (depth === 0) return j
      } else j++
    }
    return this.src.length
  }

  private backtick(): string {
    let j = this.i + 1
    let s = ''
    while (j < this.src.length && this.src[j] !== '`') {
      if (this.src[j] === '\\' && j + 1 < this.src.length) {
        s += this.src[j + 1]
        j += 2
      } else s += this.src[j++]
    }
    this.i = j + 1
    return s
  }

  /** `<( ... )` or `>( ... )`: a command whose output stands in as a file. */
  private processSub(): RawWord {
    const start = this.i
    const end = this.balanced(this.i + 1)
    const src = this.src.slice(this.i + 2, Math.max(this.i + 2, end - 1))
    this.i = end
    return { parts: [{ t: 'sub', src }], start, end }
  }
}

/** A word's text when it holds no expansion; quotes removed. */
export function literal(w: RawWord): string {
  return w.parts.map(p => (p.t === 'lit' ? p.s : '')).join('')
}

